Zg(a){return"\uc7ac\uc0dd: <hp>\uccb4\ub825</hp>\uc774 \ucc98\uc74c\uc73c\ub85c "+a+"% \uc544\ub798\ub85c \ub5a8\uc5b4\uc9c0\uba74 \ud314 \ud558\ub098\uac00 \ub2e4\uc2dc \uc790\ub77c\uc694."},
gwv(){return"\uc11d\ud654\uc758 \ub208\ube5b: \uac00\uc7a5 \uac15\ud55c Ovaling\uc744 \ub208\ube5b\uc73c\ub85c <fx:petrify>\ub3cc</fx>\ub85c \ub9cc\ub4e4\uc5b4\uc694. <fx:heal>\ud68c\ubcf5</fx>\ud558\uac70\ub098 <fx:cleanse>\uc815\ud654</fx>\ud558\uba74 \ub2e4\uc2dc \ud480\ub824\ub098\uc694."},
Mq(a,b,c,d){return""+a+"% \ud655\ub960\ub85c "+b+" "+c+" \ub3d9\uc548 [!\ud68c\ubcf5 \uac10\uc18c!]\ub97c \uc918\uc694: \ud68c\ubcf5\ub7c9\uc774 "+d+"% \uc904\uc5b4\uc694."},
