US(a){return"\ud300\uc758 Ovaling\uc774 <hp>\uccb4\ub825</hp>\uc758 15% \uc774\uc0c1\uc778 \uacf5\uaca9\uc744 \ubc84\ud2f0\uba74 \uc989\uc2dc <hp>\uccb4\ub825</hp>\uc758 "+a+"% <fx:shield>\ubcf4\ud638\ub9c9</fx>\uc744 \uc5bb\uc5b4\uc694."},
V9(a){return"\uc804\ud22c\uc640 \uc0c8 \uc6e8\uc774\ube0c\uac00 \uc2dc\uc791\ub420 \ub54c \uc774\ubbf8 [[\ud134 \uac8c\uc774\uc9c0 "+a+"%]]\ub97c \uac00\uc9c0\uace0 \uc788\uc5b4\uc694."},
VT(a){return"\ud56d\uc0c1 [[<spd>\uc18d\ub3c4</spd> +"+a+"%]]."},
VA(a){return"<hp>\uccb4\ub825</hp>\uc774 "+a+"%\ubcf4\ub2e4 \ub9ce\uc740 \ub3d9\uc548 \uc801\uc758 \ub2e8\uc77c \uacf5\uaca9\uc774 <fx:taunt>\ub3c4\ubc1c</fx>\ucc98\ub7fc \uc790\uc2e0\uc5d0\uac8c \uc640\uc694. \uadf8\ub3d9\uc548 <fx:damage_reduction>\ubc1b\ub294 \ud53c\ud574\uac00 20% \uc904\uc5b4\uc694</fx>."},
